class Solution:
    def partitionLabels(self, S: str) -> List[int]:
        maxPos = {}
        for i in range(len(S)):
            maxPos[S[i]] = i

        res = []
        start = 0
        scannedCharMaxPos = 0
        for i in range(len(S)):
            curCharMaxPos = maxPos[S[i]]
            if curCharMaxPos > scannedCharMaxPos:
                scannedCharMaxPos = curCharMaxPos
            if i == scannedCharMaxPos:
                res.append(i - start + 1)
                start = i + 1
        return res
